        return ADCS_E_NULL;
    }
    if ((!adcs_is_finite_vec3(w)) || (!isfinite(dt)) || (dt < 0.0)) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    if (adcs_quat_normalize(q, &q_hat) != ADCS_OK) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    norm_w = adcs_vec3_norm(w);
    theta = norm_w * dt;

    if (theta <= ADCS_EPS_NORM) {
        dq.w = 1.0;
        dq.x = 0.5 * w->x * dt;
        dq.y = 0.5 * w->y * dt;
        dq.z = 0.5 * w->z * dt;
    } else {
        half_theta = 0.5 * theta;
        s = sin(half_theta) / norm_w;
        dq.w = cos(half_theta);
        dq.x = s * w->x;
        dq.y = s * w->y;
        dq.z = s * w->z;
    }

