    adcs_quat_t q_hat, dq, next;
    double norm_w, theta, half, s;

    /* Failure handling: Null pointers */
    if ((q == NULL) || (w == NULL) || (out == NULL)) {
        if (out != NULL) *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_NULL;
    }

    /* Failure handling: Nonfinite rate/time or negative dt */
    if ((!adcs_is_finite_vec3(w)) || (!isfinite(dt)) || (dt < 0.0)) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    /* Normalize q */
    if (adcs_quat_normalize(q, &q_hat) != ADCS_OK) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    /* Calculate theta and construct dq */
    norm_w = adcs_vec3_norm(w);
    theta = norm_w * dt;

    if (theta <= ADCS_EPS_NORM) {
        /* Linear approximation for small angles */
        dq = (adcs_quat_t){1.0, 0.5 * w->x * dt, 0.5 * w->y * dt, 0.5 * w->z * dt};
    } else {
        /* Exact propagation */
        half = 0.5 * theta;
        s = sin(half) / norm_w;
        dq = (adcs_quat_t){cos(half), s * w->x, s * w->y, s * w->z};
    }

    /* Propagate: out = canonicalize(normalize(dq tensor-product q_hat)) */
    next = adcs_quat_multiply(&dq, &q_hat);

    /* Normalize result */
    if (adcs_quat_normalize(&next, out) != ADCS_OK) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    /* Canonicalize w >= 0 */
    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }

    return ADCS_OK;
}

